example:
agent Tally {
    key id: String
    store count: Cell[Int]

    on GET("/count") () -> Effect[Result[Int, String]] {   // ✗ a route is a service's
        Ok(count)
    }
}

agent Tally {
    key id: String
    store count: Cell[Int]

    on call get() -> Effect[Result[Int, String]] {         // ✓ the agent's own operation
        Ok(count)
    }
}
